<?php require __DIR__.'/_init.php';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';if($action==='delete'){$pdo->prepare('DELETE FROM coupons WHERE id=?')->execute([(int)$_POST['id']]);flash('success','کد تخفیف حذف شد.');}else{$code=strtoupper(trim((string)($_POST['code']??'')));$type=($_POST['discount_type']??'percent')==='fixed'?'fixed':'percent';$value=max(0,(int)($_POST['discount_value']??0));$min=max(0,(int)($_POST['min_order']??0));$max=($_POST['max_uses']??'')===''?null:max(1,(int)$_POST['max_uses']);$expires=trim((string)($_POST['expires_at']??''))?:null;if(!preg_match('/^[A-Z0-9_-]{3,80}$/',$code)||$value<1||($type==='percent'&&$value>100)){flash('error','اطلاعات کد تخفیف معتبر نیست.');}else{try{$pdo->prepare('INSERT INTO coupons(code,discount_type,discount_value,min_order,max_uses,expires_at,is_active,created_at) VALUES(?,?,?,?,?,?,1,NOW())')->execute([$code,$type,$value,$min,$max,$expires]);flash('success','کد تخفیف ساخته شد.');}catch(Throwable $e){flash('error','کد تکراری است یا ذخیره انجام نشد.');}}}header('Location: '.site_url('admin/coupons.php'));exit;}$rows=$pdo->query('SELECT * FROM coupons ORDER BY id DESC')->fetchAll();render_header('کدهای تخفیف');?><main class="container"><div class="page-title"><h1>کدهای تخفیف</h1><p>کد درصدی یا مبلغ ثابت، حداقل مبلغ و سقف استفاده.</p></div><div class="admin-layout"><aside class="admin-nav"><a href="<?=e(site_url('admin/index.php'))?>">داشبورد</a><a href="<?=e(site_url('admin/products.php'))?>">محصولات</a><a href="<?=e(site_url('admin/orders.php'))?>">سفارش‌ها</a><a href="<?=e(site_url('admin/print-options.php'))?>">گزینه‌های چاپ</a></aside><section class="admin-content"><div class="form-card"><h2>کد جدید</h2><form method="post"><?=csrf_field()?><div class="form-grid"><div class="form-group"><label>کد تخفیف</label><input name="code" required placeholder="WELCOME10"></div><div class="form-group"><label>نوع</label><select name="discount_type"><option value="percent">درصدی</option><option value="fixed">مبلغ ثابت</option></select></div><div class="form-group"><label>مقدار (درصد یا تومان)</label><input type="number" name="discount_value" min="1" required></div><div class="form-group"><label>حداقل مبلغ سفارش (تومان)</label><input type="number" name="min_order" min="0" value="0"></div><div class="form-group"><label>حداکثر تعداد استفاده (خالی=بدون محدودیت)</label><input type="number" name="max_uses" min="1"></div><div class="form-group"><label>تاریخ انقضا (اختیاری، YYYY-MM-DD HH:MM:SS)</label><input name="expires_at" placeholder="2027-01-01 23:59:59"></div></div><button class="btn">ساخت کد</button></form></div><div class="table-wrap"><table class="table"><tr><th>کد</th><th>تخفیف</th><th>حداقل خرید</th><th>استفاده</th><th></th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['code'])?></td><td><?=$r['discount_type']==='percent'?e($r['discount_value']).'%':money($r['discount_value'])?></td><td><?=money($r['min_order'])?></td><td><?=e($r['used_count'])?> / <?=e($r['max_uses']??'∞')?></td><td><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="small-btn danger">حذف</button></form></td></tr><?php endforeach;?></table></div></section></div></main><?php render_footer();?>
